<?php
require __DIR__ . '/../includes/config.php';
require_admin();
$shopId = (int)$_SESSION['shop_id'];
$stmt = db()->prepare('SELECT id,name,description,price,category,stock,active FROM products WHERE shop_id = ? ORDER BY id DESC');
$stmt->execute([$shopId]); $products = $stmt->fetchAll();
$shopStmt = db()->prepare('SELECT name,slug FROM shops WHERE id = ?'); $shopStmt->execute([$shopId]); $shop = $shopStmt->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><link rel="stylesheet" href="../assets/style.css"><style>.dash{max-width:1000px;margin:40px auto;padding:0 20px}.panel{background:white;border:1px solid var(--line);border-radius:10px;padding:20px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}th{color:var(--muted)}.pill{background:#f4f4f5;border-radius:20px;padding:5px 9px;font-size:11px}.actions{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.small-button{padding:9px 12px;font-size:12px}</style></head><body><header class="topbar"><a class="brand" href="../index.php?shop=<?= e($shop['slug']) ?>"><?= e($shop['name']) ?></a><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="admin-link" type="submit" style="border:0;background:transparent;cursor:pointer">Sign out</button></form></header><main class="dash"><span class="eyebrow">OVERVIEW</span><h1 style="font-size:36px">Shop dashboard</h1><p style="color:var(--muted)">Manage the products published in your storefront.</p><div class="panel"><div class="actions"><h2 style="font-size:21px;margin:0">Products (<?= count($products) ?>)</h2><a class="button small-button" href="product.php">Add product</a></div><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= number_format((float)$p['price'],2) ?></td><td><?= (int)$p['stock'] ?></td><td><span class="pill"><?= $p['active'] ? 'Active' : 'Hidden' ?></span></td><td><a href="product.php?id=<?= (int)$p['id'] ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></main></body></html>
